"use strict";
(()=>{
  const $=s=>document.querySelector(s),root=$("#mRoot"),scale=$("#mScale"),octave=$("#mOctave"),music=$("#mMusic"),preview=$("#mScalePreview"),summary=$("#mSummary"),backingRoot=$("#mBackingRoot"),backingMode=$("#mBackingMode"),backingStyle=$("#mBackingStyle"),backingAnswer=$("#mBackingAnswer");
  const names=["Do","Do♯","Ré","Mi♭","Mi","Fa","Fa♯","Sol","La♭","La","Si♭","Si"],intervals={blues:[0,3,5,6,7,10,12],major:[0,2,4,5,7,9,11,12],minor:[0,2,3,5,7,8,10,12],pentatonic:[0,2,4,7,9,12],minorPentatonic:[0,3,5,7,10,12]},labels={blues:"Blues",major:"Majeure",minor:"Mineure",pentatonic:"Penta. majeure",minorPentatonic:"Penta. mineure",allOctaves:"Toutes les octaves"};
  let source="scale",mode="hero",audio=null;
  const backingProfiles={jazz:{major:{safe:[0,2,4,7,9],color:[5,11]},minor:{safe:[0,3,5,7,10],color:[2,8]}},blues:{major:{safe:[0,2,3,4,7,9],color:[10]},minor:{safe:[0,3,5,6,7,10],color:[2]}},soul:{major:{safe:[0,2,4,7,9],color:[3,10]},minor:{safe:[0,3,5,7,10],color:[2,9]}}};
  const comfortableOctave=rootValue=>rootValue>=7?3:4,scaleBase=()=>12*((octave.value==="auto"?comfortableOctave(Number(root.value)):Number(octave.value))+1)+Number(root.value);
  function validateOctave(){const octaveField=octave.closest("label");octaveField.hidden=scale.value==="allOctaves";const low=octave.querySelector('option[value="3"]'),rootValue=Number(root.value);low.disabled=rootValue<6;if(low.disabled&&octave.value==="3")octave.value="auto";$("#mOctaveHint").textContent=low.disabled?`${names[rootValue]}3 est sous la tessiture standard. La trompette commence à Fa♯3.`:"";}
  function staffStep(midi){const diatonic=[0,0,1,1,2,3,3,4,4,5,5,6];return (Math.floor(midi/12)-5)*7+diatonic[midi%12]}
  function compactMidi(midi){while(midi>74)midi-=12;while(midi<55)midi+=12;return midi}
  function allOctaveMidis(rootValue){const out=[];for(let midi=54;midi<=90;midi++)if(midi%12===rootValue)out.push(midi);return out}
  function tone(midi){audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const n=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type="triangle";o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(.001,n);g.gain.exponentialRampToValueAtTime(.18,n+.015);g.gain.exponentialRampToValueAtTime(.001,n+.45);o.connect(g).connect(audio.destination);o.start(n);o.stop(n+.46)}
  const backingScaleType=()=>backingStyle.value==="blues"?"blues":backingMode.value==="minor"?"minorPentatonic":"pentatonic";
  function renderBacking(){const concertRoot=Number(backingRoot.value),profile=backingProfiles[backingStyle.value][backingMode.value],writtenRoot=(concertRoot+2)%12,modeLabel=backingMode.value==="major"?"majeur":"mineur";backingAnswer.innerHTML=`<div class="m-backing-key"><small>À LA TROMPETTE SIB</small><strong>${names[writtenRoot]} ${modeLabel}</strong><span>sur un backing concert ${names[concertRoot]} ${modeLabel}</span></div><p>Notes sûres</p><div class="m-backing-notes safe"></div><p>Couleurs ${backingStyle.selectedOptions[0].textContent}</p><div class="m-backing-notes colors"></div>`;const add=(interval,kind)=>{let midi=60;while(midi%12!==writtenRoot)midi++;midi+=interval;const vals=window.TrumpetFingerings.primary(midi),button=document.createElement("button");button.type="button";button.className=kind;button.innerHTML=`<b>${names[midi%12]}</b><small>concert ${names[(concertRoot+interval)%12]}</small><span>${(vals.length?vals:[0]).map(v=>`<i class="v${v}">${v}</i>`).join("")}</span>`;button.onclick=()=>tone(midi);backingAnswer.querySelector(kind==="color"?".colors":".safe").appendChild(button)};profile.safe.forEach(i=>add(i,"safe"));profile.color.forEach(i=>add(i,"color"))}
  function render(){
    validateOctave();
    const isAllOctaves=scale.value==="allOctaves",base=scaleBase(),midis=isAllOctaves?allOctaveMidis(Number(root.value)):intervals[scale.value].map(step=>base+step);
    preview.innerHTML='<span class="m-preview-clef">𝄞</span><span class="m-preview-lines"></span>';
    midis.forEach((midi,index)=>{const vals=window.TrumpetFingerings.primary(midi),hard=midi>window.TrumpetFingerings.highestWrittenMidi,button=document.createElement("button");button.className=hard?"hard":"";button.style.gridColumn=String(index+2);button.style.setProperty("--y",`${75-staffStep(compactMidi(midi))*4}px`);button.innerHTML=`<i></i><b>${names[midi%12]}${Math.floor(midi/12)-1}</b><span>${(vals.length?vals:[0]).map(v=>`<em class="v${v}">${v}</em>`).join("")}</span>`;button.setAttribute("aria-label",`${names[midi%12]}, ${vals.length?`pistons ${vals.join(" et ")}`:"pistons libres"}${hard?", note avancée au-delà de la tessiture standard":""}`);button.onclick=()=>tone(midi);preview.appendChild(button)});
    update();
  }
  function update(){const modeName={hero:"Héros",instrument:"Instrument",partition:"Partition"}[mode],isAllOctaves=scale.value==="allOctaves",startOctave=Math.floor(scaleBase()/12)-1;const scaleSummary=isAllOctaves?`${names[Number(root.value)]} · toutes les octaves`:`${names[Number(root.value)]}${startOctave} · ${labels[scale.value]}`;if(source==="scale")summary.textContent=`${scaleSummary} · ${modeName}`;else if(source==="backing")summary.textContent=`Backing ${names[Number(backingRoot.value)]} ${backingMode.value==="major"?"majeur":"mineur"} · ${modeName}`;else summary.textContent=`${music.selectedOptions[0].textContent} · ${modeName}`;renderBacking()}
  document.querySelectorAll("[data-tab]").forEach(tab=>tab.onclick=()=>{source=tab.dataset.tab;document.querySelectorAll("[data-tab]").forEach(x=>x.classList.toggle("active",x===tab));document.querySelectorAll("[data-panel]").forEach(p=>{const on=p.dataset.panel===source;p.hidden=!on;p.classList.toggle("active",on)});update()});
  document.querySelectorAll("[data-mode]").forEach(button=>button.onclick=()=>{mode=button.dataset.mode;document.querySelectorAll("[data-mode]").forEach(x=>x.classList.toggle("active",x===button));$("#mModeHint").textContent={hero:"Réflexes visuels",instrument:"Trompette en mouvement",partition:"Lecture sans distraction"}[mode];update()});
  root.onchange=render;scale.onchange=render;octave.onchange=render;music.onchange=update;backingRoot.onchange=update;backingMode.onchange=update;backingStyle.onchange=update;
  $("#mLaunch").onclick=()=>{const q=new URLSearchParams({mode});if(source==="scale"){q.set("root",root.value);q.set("scale",scale.value);q.set("octave",octave.value)}else if(source==="backing"){q.set("root",backingRoot.value);q.set("scale",backingScaleType());q.set("octave","auto")}else q.set("track",music.value);location.href=`mobile-player.html?${q}`};render();
})();
